R = {"title": "Sales", "columns": ["region", "units"], "rows": [["north", 12], ["south", 7], ["east", 3.5]]}
class _Intermediate(BaseRenderer):
    pass  # no name -> not a format
class Tsv(_Intermediate):
    name = "tsv"
    def render_rows(self, report): return ["\t".join(map(str, r)) for r in report["rows"]]
fmts = available_formats()
assert "tsv" in fmts and all(f != "_Intermediate" for f in fmts), fmts
assert render(R, "tsv", max_rows=2) == "north\t12\nsouth\t7"
print("nested subclass discovered; max_rows applied via base class:", fmts)
class Tsv2(BaseRenderer):
    name = "tsv"
    def render_rows(self, report): return []
try:
    available_formats()
except TypeError as e:
    print("duplicate ->", e)
else:
    raise AssertionError("duplicate name not detected")
EOF

